// Format Alert Message for Telegram (HTML Mode)
const payload = $input.item.json.body || $input.item.json;

const severity = (payload.severity || 'INFO').toUpperCase();
const severityEmoji = {
  'CRITICAL': '🚨',
  'HIGH': '🟠',
  'MEDIUM': '🟡',
  'LOW': '🔵',
  'INFO': 'ℹ️'
}[severity] || '⚠️';

const title = payload.title || 'Notification Alert';
const incidentId = payload.incident_id || 'N/A';
const host = payload.host || 'N/A';
const riskScore = payload.risk_score !== undefined ? payload.risk_score : 'N/A';
const recommendation = payload.recommendation || 'N/A';
const nowStr = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });

let message = `${severityEmoji} <b>AEGILON NOTIFICATION</b> ${severityEmoji}

`;
message += `<b>Title:</b> ${title}
`;
message += `<b>Severity:</b> ${severity}
`;
message += `<b>Risk Score:</b> ${riskScore}/100
`;
message += `<b>Host:</b> <code>${host}</code>
`;
message += `<b>Incident ID:</b> <code>${incidentId}</code>
`;
if (recommendation !== 'N/A') {
  message += `<b>Recommendation:</b> ${recommendation}
`;
}
message += `
⏰ <b>Timestamp:</b> ${nowStr} WIB`;

const botToken = payload.bot_token || $env.TELEGRAM_BOT_TOKEN || '8896459477:AAECPoVHIqELcWQci65ra4ML0GCH4KjhubU';
const chatId = payload.chat_id || $env.TELEGRAM_CHAT_ID || '1345953125';

return {
  json: {
    bot_token: botToken,
    chat_id: chatId,
    text: message,
    parse_mode: 'HTML'
  }
};
